import { FADE_SECONDS, LEVEL, mixedGain, readMix, safeVolume, type SavedMix, type SoundId } from './focusSoundRules';

export * from './focusSoundRules';

/*
 * The sound itself. Everything is generated by the browser from noise and filters: nothing is
 * downloaded, nothing needs a licence, it all works offline, and no recording means no chance of a
 * voice or a lyric slipping in.
 *
 * One engine for the whole app, kept outside React, so moving between Notes and Flashcards doesn't
 * restart the sound or quietly start a second copy of it. Sound only ever begins from a press.
 */
const KEY = 'study-forge-focus-mix';
export const FOCUS_CHANGED = 'study-forge-focus-changed';

interface Layer {
  id: SoundId;
  volume: number;
  source: AudioBufferSourceNode;
  gain: GainNode;
  shaping: AudioNode[];
}

let context: AudioContext | null = null;
let master: GainNode | null = null;
let layers: Layer[] = [];
let mix: SavedMix = { layers: [], master: 0.6 };
let timerEndsAt = 0;
let timerHandle: ReturnType<typeof setTimeout> | null = null;
const listeners = new Set<() => void>();

try {
  mix = readMix(JSON.parse(localStorage.getItem(KEY) ?? 'null'));
} catch {
  // A private window simply starts from the usual mix.
}

function remember() {
  /*
   * Stopping everything doesn't forget what was playing. Otherwise the mix is wiped the moment
   * the student stops, and bringing back "what you last had" could never bring back anything.
   * The volumes are always kept; the layers are only replaced while something is actually on.
   */
  const playing = layers.map((layer) => ({ id: layer.id, volume: layer.volume }));
  mix = { layers: playing.length > 0 ? playing : mix.layers, master: mix.master };
  try {
    localStorage.setItem(KEY, JSON.stringify(mix));
  } catch {
    // Not being able to remember the mix is no reason to stop the sound.
  }
}

const announce = () => {
  listeners.forEach((listener) => listener());
  if (typeof window !== 'undefined') window.dispatchEvent(new CustomEvent(FOCUS_CHANGED));
};

/** Noise of each colour, made once and looped. Ten seconds is long enough that no pattern is heard. */
function noiseBuffer(ctx: AudioContext, kind: 'white' | 'pink' | 'brown'): AudioBuffer {
  const length = ctx.sampleRate * 10;
  const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  if (kind === 'white') {
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }
  if (kind === 'brown') {
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.5;
    }
    return buffer;
  }
  // Pink: the usual bank of filters on white noise, which gives an even, full sound.
  let b0 = 0; let b1 = 0; let b2 = 0; let b3 = 0; let b4 = 0; let b5 = 0; let b6 = 0;
  for (let i = 0; i < length; i++) {
    const white = Math.random() * 2 - 1;
    b0 = 0.99886 * b0 + white * 0.0555179;
    b1 = 0.99332 * b1 + white * 0.0750759;
    b2 = 0.969 * b2 + white * 0.153852;
    b3 = 0.8665 * b3 + white * 0.3104856;
    b4 = 0.55 * b4 + white * 0.5329522;
    b5 = -0.7616 * b5 - white * 0.016898;
    data[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.11;
    b6 = white * 0.115926;
  }
  return buffer;
}

const buffers = new Map<string, AudioBuffer>();
function bufferFor(ctx: AudioContext, kind: 'white' | 'pink' | 'brown'): AudioBuffer {
  const found = buffers.get(kind);
  if (found) return found;
  const made = noiseBuffer(ctx, kind);
  buffers.set(kind, made);
  return made;
}

/** A slow, gentle rise and fall, so a sound breathes instead of sitting perfectly still. */
function breathe(ctx: AudioContext, target: AudioParam, depth: number, everySeconds: number): AudioNode[] {
  const slow = ctx.createOscillator();
  slow.frequency.value = 1 / everySeconds;
  const amount = ctx.createGain();
  amount.gain.value = depth;
  slow.connect(amount).connect(target);
  slow.start();
  return [slow, amount];
}

/** Builds one sound and returns the nodes that shape it. */
function buildLayer(ctx: AudioContext, id: SoundId, out: GainNode): { source: AudioBufferSourceNode; shaping: AudioNode[] } {
  const source = ctx.createBufferSource();
  source.loop = true;
  const shaping: AudioNode[] = [];
  if (id === 'white' || id === 'pink' || id === 'brown') {
    source.buffer = bufferFor(ctx, id);
    source.connect(out);
  } else if (id === 'fan') {
    // A fan is mostly low noise with a steady whirr over it.
    source.buffer = bufferFor(ctx, 'brown');
    const tone = ctx.createBiquadFilter();
    tone.type = 'lowpass';
    tone.frequency.value = 520;
    const whirr = ctx.createGain();
    whirr.gain.value = 0.85;
    source.connect(tone).connect(whirr).connect(out);
    shaping.push(tone, whirr, ...breathe(ctx, whirr.gain, 0.1, 7));
  } else {
    // Wind is air moving through a narrow band that drifts slowly up and down.
    source.buffer = bufferFor(ctx, 'pink');
    const band = ctx.createBiquadFilter();
    band.type = 'bandpass';
    band.frequency.value = 480;
    band.Q.value = 0.7;
    source.connect(band).connect(out);
    shaping.push(band, ...breathe(ctx, band.frequency, 260, 13));
  }
  source.start();
  return { source, shaping };
}

function applyGains() {
  if (!context || !master) return;
  const count = layers.length;
  for (const layer of layers) {
    // The sound's own calibration is part of its gain, so five sounds that are built very
    // differently still come out at the same loudness.
    const level = mixedGain(layer.volume, count) * LEVEL[layer.id];
    layer.gain.gain.setTargetAtTime(level, context.currentTime, 0.08);
  }
  master.gain.setTargetAtTime(safeVolume(mix.master, 0.6), context.currentTime, 0.08);
}

/**
 * A quarter of a second of real silence, built here rather than shipped as a file.
 */
function silentWav(): string {
  const rate = 8000;
  const samples = 2000;
  const bytes = new Uint8Array(44 + samples);
  const view = new DataView(bytes.buffer);
  const ascii = (at: number, text: string) => { for (let i = 0; i < text.length; i += 1) view.setUint8(at + i, text.charCodeAt(i)); };
  ascii(0, 'RIFF'); view.setUint32(4, 36 + samples, true); ascii(8, 'WAVE');
  ascii(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true); view.setUint16(22, 1, true);
  view.setUint32(24, rate, true); view.setUint32(28, rate, true); view.setUint16(32, 1, true); view.setUint16(34, 8, true);
  ascii(36, 'data'); view.setUint32(40, samples, true);
  bytes.fill(128, 44); // Unsigned eight-bit silence sits at the middle of the range, not at zero.
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return `data:audio/wav;base64,${btoa(binary)}`;
}

let keeper: HTMLAudioElement | null = null;

/**
 * Tells the phone that this is music, not a notification beep.
 *
 * On an iPhone, sound made by the browser's audio engine alone is treated as incidental and is
 * silenced by the physical mute switch — so the sound plays, the volume is up, and nothing comes
 * out. Playing a real (and genuinely silent) audio file alongside it moves the page into the
 * category used for playback, which the mute switch doesn't govern. It costs nothing audible and
 * is the only way round it from a web page. Started inside the same press, because a phone will
 * not start playback later.
 */
function claimPlayback(): void {
  try {
    if (!keeper) {
      keeper = new Audio(silentWav());
      keeper.loop = true;
      keeper.setAttribute('playsinline', '');
    }
    void keeper.play().catch(() => undefined);
  } catch {
    // No audio element available: the sound still plays, it just may obey the mute switch.
  }
}

function releasePlayback(): void {
  try {
    keeper?.pause();
  } catch {
    // Nothing to release.
  }
}

/** Starts a sound. Must be called from a press, because browsers only allow sound then. */
export function playSound(id: SoundId, volume = 0.5): void {
  if (layers.some((layer) => layer.id === id)) return;
  claimPlayback();
  context ??= new (window.AudioContext ?? (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
  void context.resume();
  if (!master) {
    master = context.createGain();
    master.gain.value = safeVolume(mix.master, 0.6);
    master.connect(context.destination);
  }
  // A timer part-way through fading out has turned the overall volume down. Starting a sound
  // again means the student wants to hear it, so the fade is called off rather than left silent.
  clearTimer();
  master.gain.cancelScheduledValues(context.currentTime);
  master.gain.value = safeVolume(mix.master, 0.6);
  const gain = context.createGain();
  gain.gain.value = 0;
  gain.connect(master);
  const { source, shaping } = buildLayer(context, id, gain);
  layers.push({ id, volume: safeVolume(volume), source, gain, shaping });
  applyGains();
  remember();
  announce();
}

export function stopSound(id: SoundId): void {
  const layer = layers.find((entry) => entry.id === id);
  if (!layer) return;
  layers = layers.filter((entry) => entry !== layer);
  try {
    layer.source.stop();
  } catch {
    // Already stopped.
  }
  layer.shaping.forEach((node) => { if ('stop' in node) (node as OscillatorNode).stop(); node.disconnect(); });
  layer.gain.disconnect();
  applyGains();
  remember();
  announce();
}

export function stopAll(): void {
  [...layers].forEach((layer) => stopSound(layer.id));
  clearTimer();
  releasePlayback();
  announce();
}

export function setLayerVolume(id: SoundId, volume: number): void {
  const layer = layers.find((entry) => entry.id === id);
  if (!layer) return;
  layer.volume = safeVolume(volume);
  applyGains();
  remember();
  announce();
}

export function setMasterVolume(volume: number): void {
  mix = { ...mix, master: safeVolume(volume) };
  applyGains();
  remember();
  announce();
}

export const playingSounds = (): { id: SoundId; volume: number }[] => layers.map((layer) => ({ id: layer.id, volume: layer.volume }));
export const isPlaying = (id: SoundId): boolean => layers.some((layer) => layer.id === id);
export const anyPlaying = (): boolean => layers.length > 0;
export const masterVolume = (): number => safeVolume(mix.master, 0.6);
export const savedMix = (): SavedMix => mix;
export const timerLeft = (): number => (timerEndsAt ? Math.max(0, timerEndsAt - Date.now()) : 0);

function clearTimer() {
  if (timerHandle) clearTimeout(timerHandle);
  timerHandle = null;
  timerEndsAt = 0;
}

/** Stops the sound after a while, fading out at the end so it never cuts off suddenly. */
export function setTimer(minutes: number | null): void {
  clearTimer();
  if (minutes && minutes > 0) {
    timerEndsAt = Date.now() + minutes * 60_000;
    const fadeAt = Math.max(0, minutes * 60_000 - FADE_SECONDS * 1000);
    timerHandle = setTimeout(() => {
      if (context && master) master.gain.setTargetAtTime(0, context.currentTime, FADE_SECONDS / 3);
      timerHandle = setTimeout(() => { stopAll(); if (master && context) master.gain.value = safeVolume(mix.master, 0.6); }, FADE_SECONDS * 1000);
    }, fadeAt);
  }
  announce();
}

export function subscribeFocus(listener: () => void): () => void {
  listeners.add(listener);
  return () => { listeners.delete(listener); };
}
